import re, sys
from html.parser import HTMLParser

src = open("preview.html", encoding="utf-8").read()
VOID = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr","path","rect","circle","line","text","use","pattern","stop","polyline","polygon"}

class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]; self.ids=[]; self.refs=[]; self.tags={}
    def handle_starttag(self, tag, attrs):
        d=dict(attrs); self.tags[tag]=self.tags.get(tag,0)+1
        if "id" in d: self.ids.append(d["id"])
        for a in ("aria-controls","aria-labelledby"):
            if a in d: self.refs.append((a,d[a]))
        if tag not in VOID: self.stack.append((tag,self.getpos()))
    def handle_startendtag(self, tag, attrs):
        d=dict(attrs)
        if "id" in d: self.ids.append(d["id"])
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.errors.append(f"stray </{tag}> at {self.getpos()}"); return
        top,pos=self.stack.pop()
        if top!=tag:
            self.errors.append(f"mismatch: </{tag}> at {self.getpos()} closes <{top}> opened at {pos}")

p=P(); p.feed(src)
print("tag errors:", p.errors or "none")
print("unclosed:", [(t,pos) for t,pos in p.stack] or "none")
dupes=[i for i in set(p.ids) if p.ids.count(i)>1]
print("duplicate ids:", dupes or "none")
missing=[(a,v) for a,v in p.refs if v not in p.ids]
print("broken aria refs:", missing or "none")
print("tabs:", p.tags.get("button"), "panels:", src.count('role="tabpanel"'))
print("role=tablist:", src.count('role="tablist"'), "role=tab:", src.count('role="tab"'))

# external resource check
print("http(s) refs:", re.findall(r'https?://', src) or "none")
print("src=/<link/@import/url(http):", re.findall(r'(?:\ssrc=|@import|<link|url\((?!#))', src) or "none")
print("url() uses:", re.findall(r'url\([^)]*\)', src))

def balance(text, pairs):
    stack=[]; line=1
    i=0
    in_s=None; in_c=False; esc=False
    while i<len(text):
        ch=text[i]
        if ch=="\n": line+=1
        if in_c:
            if ch=="\n": in_c=False
        elif in_s:
            if esc: esc=False
            elif ch=="\\": esc=True
            elif ch==in_s: in_s=None
        else:
            if ch in "\"'`": in_s=ch
            elif text[i:i+2]=="//": in_c=True; i+=2; continue
            elif text[i:i+2]=="/*": 
                j=text.find("*/",i+2); line+=text[i:j].count("\n"); i=j+2; continue
            elif ch in "([{": stack.append((ch,line))
            elif ch in ")]}":
                if not stack: return f"extra {ch} at line {line}"
                o,l=stack.pop()
                if pairs[o]!=ch: return f"mismatch {o}@{l} vs {ch}@{line}"
        i+=1
    return stack or "balanced"

css = re.search(r"<style>(.*?)</style>", src, re.S).group(1)
js = re.search(r"<script>(.*?)</script>", src, re.S).group(1)
print("css block:", balance(css, {"(":")","{":"}"}))
# js: strip comments/strings via crude scan for bracket balance
print("js block:", balance(js, {"(":")","{":"}","[":"]"}))
print("js lines:", js.count("\n"), "script tags:", src.count("<script"))
