/* ------------------------------------------------------------------
   Scientific mode (task 2). Same tokens and primitives as the shell;
   this block only adds the pieces the expression console needs:
   angle switch, inline message line, caret, history list.
------------------------------------------------------------------- */

/* angle unit switch */
.seg {
  display: inline-flex;
  border: 1px solid var(--hair-strong);
  border-radius: var(--r);
  overflow: hidden;
}
.seg__btn {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--dim);
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  line-height: 1;
  padding: 6px 10px 7px;
  cursor: pointer;
  transition: background-color 130ms ease, color 130ms ease;
}
.seg__btn + .seg__btn { border-left: 1px solid var(--hair-strong); }
.seg__btn:hover { color: var(--bone); }
.seg__btn[aria-pressed="true"] {
  background: var(--accent-soft);
  color: var(--accent);
}

/* expression caret + empty state */
.readout__expr.is-empty::before {
  content: "enter an expression";
  color: var(--dim);
  opacity: 0.75;
}
.sci-caret {
  display: inline-block;
  width: 1px;
  height: 1.05em;
  margin-left: 2px;
  transform: translateY(3px);
  background: var(--accent);
  animation: sci-caret 1.1s steps(1) infinite;
}
@keyframes sci-caret {
  0%, 49% { opacity: 1; }
  50%, 99% { opacity: 0; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .sci-caret { animation: none; }
}

/* inline message line: errors, never a throw */
.sci-msg {
  font-family: var(--mono);
  font-size: 0.75rem;
  line-height: 1.4;
  letter-spacing: 0.01em;
  color: var(--dim);
  min-height: 1.05rem;
}
.sci-msg--error { color: #ff9d86; }
.sci-msg--error::before { content: "! "; font-weight: 600; }

/* live preview vs settled result vs error */
.readout__value { transition: color 140ms ease; }
.readout__value.is-preview { color: var(--mist); }
.readout__value.is-error { color: #ff9d86; }

/* active key (2nd function set) */
.key.is-active {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
}

/* equals key spans two columns of the five-key grid */
#sci-keypad .key--eq { grid-column: span 2; }

.sci-hint {
  font-size: 0.6875rem;
  line-height: 1.75;
  color: var(--dim);
  max-width: 46ch;
}

/* history list ------------------------------------------------------*/

.sci-history {
  display: grid;
  border: 1px solid var(--hair);
  border-radius: var(--r);
  background: var(--screen);
  overflow: hidden;
}

.sci-history__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s2);
  padding: var(--s2) var(--s3);
  border-bottom: 1px solid var(--hair);
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
}

.sci-history__clear {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--dim);
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: lowercase;
  padding: 3px 6px;
  margin: -3px -6px -3px 0;
  border-radius: 2px;
  cursor: pointer;
  transition: color 130ms ease, background-color 130ms ease;
}
.sci-history__clear:hover { color: var(--bone); background: var(--raised); }

.sci-history__list {
  display: grid;
  max-height: 214px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.sci-history__item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s3);
  width: 100%;
  appearance: none;
  border: 0;
  border-bottom: 1px solid var(--hair);
  background: transparent;
  padding: 8px var(--s3);
  text-align: left;
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--mist);
  cursor: pointer;
  transition: background-color 120ms ease, color 120ms ease;
}
.sci-history__list li:last-child .sci-history__item { border-bottom: 0; }
.sci-history__item:hover { background: var(--accent-soft); color: var(--bone); }
.sci-history__item:hover .sci-history__res { color: var(--accent); }

.sci-history__expr {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sci-history__res {
  flex: none;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  transition: color 120ms ease;
}

.sci-history__empty {
  padding: var(--s3);
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--dim);
}

/* desktop: readout over history in the left column, keypad on the right */
@media (min-width: 880px) {
  #sci-body {
    grid-template-columns: minmax(0, 0.84fr) minmax(0, 1fr);
    grid-template-areas:
      "readout keypad"
      "history keypad";
  }
  #sci-readout { grid-area: readout; min-height: 0; }
  #sci-body .sci-console { grid-area: keypad; }
  #sci-history { grid-area: history; }
  #sci-readout { grid-template-rows: auto auto minmax(96px, 1fr) auto; }
  #sci-readout .readout__value { align-self: end; }
}

/* ==================================================================
   ENGINE — FluxionMath
   Hand-written tokenizer, recursive-descent parser and evaluator.
   No eval, no Function constructor, no implicit coercion of input.
   Everything is inside try/catch and returns a result object, so a
   malformed expression can never throw into the page:
       FluxionMath.evaluate(src, {angle: 'deg'|'rad', scope: {...}})
         -> { ok: true, value: Number, text: String }
         -> { ok: false, error: String, empty?: true }
   Shared by every mode: the graph panel can pass scope {x: …} and the
   date panel can reuse format()/pretty().
   ================================================================== */

var FluxionMath = (function () {
  'use strict';

  var SIGNIFICANT = 12;

  function CalcError(message) { this.message = message; }
  CalcError.prototype = Object.create(Error.prototype);
  CalcError.prototype.name = 'CalcError';

  function fail(message) { throw new CalcError(message); }

  function toRad(x, angle) { return angle === 'deg' ? x * Math.PI / 180 : x; }
  function fromRad(x, angle) { return angle === 'deg' ? x * 180 / Math.PI : x; }

  var CONSTANTS = {
    pi: Math.PI,
    tau: Math.PI * 2,
    e: Math.E,
    phi: (1 + Math.sqrt(5)) / 2
  };

  var FUNCTIONS = {
    sin: function (x, a) { return Math.sin(toRad(x, a)); },
    cos: function (x, a) { return Math.cos(toRad(x, a)); },
    tan: function (x, a) {
      if (a === 'deg' && Math.abs((x - 90) / 180 - Math.round((x - 90) / 180)) < 1e-12) {
        fail('tan is undefined at 90° + 180°·k');
      }
      return Math.tan(toRad(x, a));
    },
    asin: function (x, a) {
      if (x < -1 || x > 1) fail('asin needs a value from -1 to 1');
      return fromRad(Math.asin(x), a);
    },
    acos: function (x, a) {
      if (x < -1 || x > 1) fail('acos needs a value from -1 to 1');
      return fromRad(Math.acos(x), a);
    },
    atan: function (x, a) { return fromRad(Math.atan(x), a); },
    log: function (x) {
      if (x <= 0) fail('log needs a value above zero');
      return Math.log(x) / Math.LN10;
    },
    ln: function (x) {
      if (x <= 0) fail('ln needs a value above zero');
      return Math.log(x);
    },
    log2: function (x) {
      if (x <= 0) fail('log2 needs a value above zero');
      return Math.log(x) / Math.LN2;
    },
    sqrt: function (x) {
      if (x < 0) fail('the square root of a negative number is not real');
      return Math.sqrt(x);
    },
    cbrt: function (x) {
      return Math.cbrt ? Math.cbrt(x) : (x < 0 ? -Math.pow(-x, 1 / 3) : Math.pow(x, 1 / 3));
    },
    abs: function (x) { return Math.abs(x); },
    exp: function (x) { return Math.exp(x); },
    floor: function (x) { return Math.floor(x); },
    ceil: function (x) { return Math.ceil(x); },
    round: function (x) { return Math.round(x); },
    sign: function (x) { return x === 0 ? 0 : (x < 0 ? -1 : 1); }
  };

  function has(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
  }

  /* ---------------------------------------------------------------
     Tokenizer
  --------------------------------------------------------------- */

  var OP_CHARS = '+-*/^%';
  var SYMBOLS = {
    '\u00d7': '*', '\u00b7': '*', '\u2219': '*',   /* × · ∙ */
    '\u00f7': '/', '\u2215': '/',                  /* ÷ ∕ */
    '\u2212': '-', '\u2013': '-', '\u2014': '-'    /* − – — */
  };

  function tokenize(source) {
    var tokens = [];
    var i = 0;
    var n = source.length;

    while (i < n) {
      var ch = source.charAt(i);

      /* whitespace and digit grouping separators are noise */
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' ||
          ch === '\u00a0' || ch === ',' || ch === '_') {
        i += 1;
        continue;
      }

      if (has(SYMBOLS, ch)) {
        tokens.push({ type: 'op', value: SYMBOLS[ch], text: ch });
        i += 1;
        continue;
      }

      if (ch === '\u03c0') { tokens.push({ type: 'ident', value: 'pi', text: ch }); i += 1; continue; }
      if (ch === '\u221a') { tokens.push({ type: 'ident', value: 'sqrt', text: ch }); i += 1; continue; }
      if (ch === '\u221b') { tokens.push({ type: 'ident', value: 'cbrt', text: ch }); i += 1; continue; }

      if (ch === '*') {
        if (source.charAt(i + 1) === '*') {
          tokens.push({ type: 'op', value: '^', text: '**' });
          i += 2;
          continue;
        }
        tokens.push({ type: 'op', value: '*', text: '*' });
        i += 1;
        continue;
      }

      if (OP_CHARS.indexOf(ch) >= 0) {
        tokens.push({ type: 'op', value: ch, text: ch });
        i += 1;
        continue;
      }

