  /* ---------------------------------------------------------------
     Evaluation
  --------------------------------------------------------------- */

  function evaluate(source, options) {
    var opts = options || {};
    var angle = opts.angle === 'deg' ? 'deg' : 'rad';
    var scope = opts.scope || {};

