  if (zoomInBtn) zoomInBtn.addEventListener('click', function () { zoomBy(0.8, null); });
  if (zoomOutBtn) zoomOutBtn.addEventListener('click', function () { zoomBy(1.25, null); });
  if (resetBtn) resetBtn.addEventListener('click', function () { resetView(); });

  canvas.addEventListener('pointerdown', onPointerDown);
  canvas.addEventListener('pointermove', onPointerMove);
  canvas.addEventListener('pointerup', onPointerUp);
  canvas.addEventListener('pointercancel', onPointerUp);
  canvas.addEventListener('pointerleave', onPointerLeave);
  canvas.addEventListener('wheel', onWheel, { passive: false });
  canvas.addEventListener('keydown', onKeyDown);
  canvas.addEventListener('dblclick', function (event) {
    if (event.button !== 0) return;
    zoomBy(0.7, pointerAnchor(event));
  });

  /* ---------------- resize / mode switch ---------------- */

  function onResize() {
    if (resizeQueued) return;
    resizeQueued = true;
    window.requestAnimationFrame(function () {
      resizeQueued = false;
      if (!canvas.clientWidth) return;   /* hidden: the mode switch re-measures */
      size = { w: 0, h: 0, dpr: 0 };
      refresh();
    });
  }

  if (window.ResizeObserver) {
    var observer = new ResizeObserver(onResize);
    observer.observe(canvas);
  }
  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', onResize);

  document.addEventListener('fluxion:modechange', function (event) {
    if (!event.detail || event.detail.mode !== 'graph') return;
    window.requestAnimationFrame(function () {
      size = { w: 0, h: 0, dpr: 0 };
      refresh({ revalidate: true });
    });
  });

  /* ---------------- first paint ---------------- */

  (function init() {
    for (var i = 0; i < curves.length; i += 1) {
      if (curves[i].input) curves[i].src = curves[i].input.value;
      renderRow(curves[i]);
    }
    if (autoBox) autoBox.checked = autoY;
    syncFields('all');
    syncMeta();
    if (document.body.getAttribute('data-mode') === 'graph') {
      refresh({ revalidate: true });
    } else {
      validateAll();
    }
  })();
})();
