/* ==================================================================
   GRAPH MODE — canvas plot bench
   One engine, one parser. Every sample is
       FluxionMath.evaluate(src, { angle: 'rad', scope: { x: value } })
   so the expression language is exactly the one scientific mode uses.
   evaluate() never throws: bad input becomes a message and a gap in
   the curve, and runaway windows are clamped instead of rendered.
   ================================================================== */

(function () {
  'use strict';

  var panel = document.getElementById('panel-graph');
  if (!panel || !window.FluxionMath) return;

  var Engine = window.FluxionMath;
  var canvas = document.getElementById('graph-canvas');
  var ctx = (canvas && canvas.getContext) ? canvas.getContext('2d') : null;
  if (!ctx) return;

  var layer = document.createElement('canvas');
  var lctx = layer.getContext('2d');

  var MONO = 'ui-monospace, "SF Mono", Menlo, Consolas, monospace';
  var COLORS = ['#f2b457', '#4fd1d9', '#b79bf6'];
  var TAGS = ['f\u2081', 'f\u2082', 'f\u2083'];

  var HOME = { xmin: -10, xmax: 10, ymin: -6, ymax: 6 };
  var MIN_SPAN = 1e-9;     /* closer than this and the ticks collapse */
  var MAX_SPAN = 1e12;     /* wider than this and sampling is pointless */
  var SAMPLE_MIN = 260;
  var SAMPLE_MAX = 2200;
  var PROBES = [-9.3, -2.6, -1.4, 0.5, 1, 2.7, 6.1, 13.7];
  var SYNTAX = ['unknown name', 'bracket', 'cannot start', 'unexpected',
                'nothing to calculate', 'has no number'];

  var view = { xmin: HOME.xmin, xmax: HOME.xmax, ymin: HOME.ymin, ymax: HOME.ymax };
  var autoY = true;
  var hover = null;
  var drag = null;
  var size = { w: 0, h: 0, dpr: 0 };
  var curves = [];
  var exprTimer = null;
  var fieldTimer = null;
  var resizeQueued = false;

  /* ---------------- elements ---------------- */

  var metaEl = document.getElementById('graph-meta');
  var capEl = document.getElementById('graph-cap');
  var traceXEl = document.getElementById('graph-trace-x');
  var traceListEl = document.getElementById('graph-trace-list');
  var viewMsgEl = document.getElementById('graph-view-msg');
  var autoBox = document.getElementById('graph-auto-y');
  var zoomInBtn = document.getElementById('graph-zoom-in');
  var zoomOutBtn = document.getElementById('graph-zoom-out');
  var resetBtn = document.getElementById('graph-reset');
  var fieldEls = {
    xmin: document.getElementById('gv-xmin'),
    xmax: document.getElementById('gv-xmax'),
    ymin: document.getElementById('gv-ymin'),
    ymax: document.getElementById('gv-ymax')
  };

  Array.prototype.forEach.call(panel.querySelectorAll('[data-fn]'), function (row, index) {
    var eye = row.querySelector('.gfn__eye');
    curves.push({
      row: row,
      input: row.querySelector('.gfn__input'),
      msg: row.querySelector('.gfn__msg'),
      eye: eye,
      tag: TAGS[index] || 'f' + (index + 1),
      color: COLORS[index] || '#f2b457',
      src: '',
      visible: eye ? eye.getAttribute('aria-pressed') !== 'false' : true,
      state: 'empty',
      error: '',
      points: [],
      auto: null
    });
  });

  if (!curves.length) return;

  /* ---------------- small helpers ---------------- */

  function clamp(value, lo, hi) { return value < lo ? lo : (value > hi ? hi : value); }
  function isNum(value) { return typeof value === 'number' && isFinite(value); }

  function numText(value) {
    if (!isNum(value)) return '0';
    var abs = Math.abs(value);
    if (abs !== 0 && (abs >= 1e7 || abs < 1e-4)) return String(Number(value.toPrecision(5)));
    return String(Number(value.toPrecision(6)));
  }

  function shortText(value) {
    var text;
    var abs = Math.abs(value);
    if (abs !== 0 && (abs >= 1e6 || abs < 1e-4)) text = value.toExponential(2).replace(/\.?0+e/, 'e');
    else text = String(Number(value.toPrecision(4)));
    return text.replace('-', '\u2212');
  }

  function display(value) {
    return Engine.format(value).replace('-', '\u2212');
  }

  /* ---------------- validation of one expression ---------------- */

  function inspect(src) {
    if (!src || !String(src).replace(/\s+/g, '')) return { state: 'empty', message: '' };

    var counts = {};
    var order = [];
    for (var i = 0; i < PROBES.length; i += 1) {
      var result = Engine.evaluate(src, { angle: 'rad', scope: { x: PROBES[i] } });
      if (result.ok) return { state: 'ok', message: '' };
      var message = result.error || 'this expression could not be read';
      if (!counts[message]) { counts[message] = 0; order.push(message); }
      counts[message] += 1;
    }

    /* every probe failed: a real syntax problem, or an expression with
       no real values anywhere near this part of the plane */
    var best = order[0] || 'this expression could not be read';
    for (var j = 1; j < order.length; j += 1) {
      if (counts[order[j]] > counts[best]) best = order[j];
    }
    var lowered = String(best).toLowerCase();
    for (var k = 0; k < SYNTAX.length; k += 1) {
      if (lowered.indexOf(SYNTAX[k]) >= 0) return { state: 'error', message: best };
    }
    return { state: 'domain', message: '' };
  }

  function validateAll() {
    for (var i = 0; i < curves.length; i += 1) {
      var curve = curves[i];
      var result = inspect(curve.src);
      curve.state = result.state;
      curve.error = result.message;
      renderRow(curve);
    }
  }

  function renderRow(curve) {
    var row = curve.row;
    if (row) row.classList.toggle('is-off', !curve.visible);
    if (row) row.classList.toggle('is-error', curve.state === 'error');
    if (curve.eye) {
      curve.eye.setAttribute('aria-pressed', curve.visible ? 'true' : 'false');
      curve.eye.setAttribute('aria-label', (curve.visible ? 'Hide ' : 'Show ') + curve.tag);
      curve.eye.title = (curve.visible ? 'Hide ' : 'Show ') + curve.tag;
    }
    if (!curve.msg) return;
    if (curve.state === 'error') {
      curve.msg.textContent = curve.error;
      curve.msg.classList.add('is-error');
    } else if (curve.state === 'domain') {
      curve.msg.textContent = 'no real value at the test points \u2014 try another window';
      curve.msg.classList.remove('is-error');
    } else {
      curve.msg.textContent = '';
      curve.msg.classList.remove('is-error');
    }
  }

  /* ---------------- sampling ---------------- */

  function sampleCount() {
    var count = Math.round(size.w * 1.2) + 40;
    if (!isNum(count)) count = 600;
    return Math.max(SAMPLE_MIN, Math.min(SAMPLE_MAX, count));
  }

  function fitRange(values) {
    if (!values.length) return null;
    var sorted = values.slice().sort(function (a, b) { return a - b; });
    var lo = sorted[Math.floor((sorted.length - 1) * 0.02)];
    var hi = sorted[Math.ceil((sorted.length - 1) * 0.98)];
    if (!isNum(lo) || !isNum(hi)) return null;
    if (hi - lo <= 0) {
      var mid = (lo + hi) / 2;
      var pad = Math.max(0.5, Math.abs(mid) * 0.2);
      return [mid - pad, mid + pad];
    }
    var margin = (hi - lo) * 0.1;
    return [lo - margin, hi + margin];
  }

  function prepare() {
    var count = sampleCount();
    var step = (view.xmax - view.xmin) / (count - 1);
    var low = Infinity;
    var high = -Infinity;
    var found = false;

    for (var c = 0; c < curves.length; c += 1) {
      var curve = curves[c];
      curve.points = [];
      curve.auto = null;
      if (!curve.visible || curve.state !== 'ok') continue;

      var points = [];
      var values = [];
      for (var i = 0; i < count; i += 1) {
        var x = view.xmin + step * i;
        var result = Engine.evaluate(curve.src, { angle: 'rad', scope: { x: x } });
        if (!result.ok || !isNum(result.value)) { points.push(null); continue; }
        points.push({ x: x, y: result.value });
        values.push(result.value);
      }
      curve.points = points;
      curve.auto = fitRange(values);
      if (curve.auto) {
        found = true;
        if (curve.auto[0] < low) low = curve.auto[0];
        if (curve.auto[1] > high) high = curve.auto[1];
      }
    }

    if (autoY && found && isNum(low) && isNum(high) && high > low) {
      view.ymin = low;
      view.ymax = high;
    }
  }

  /* ---------------- geometry ---------------- */

  function pxOfX(x) { return ((x - view.xmin) / (view.xmax - view.xmin)) * size.w; }
  function pxOfY(y) { return ((view.ymax - y) / (view.ymax - view.ymin)) * size.h; }
  function xAt(px) { return view.xmin + (px / size.w) * (view.xmax - view.xmin); }
  function yAt(py) { return view.ymax - (py / size.h) * (view.ymax - view.ymin); }

  function niceStep(span, wanted) {
    var raw = span / Math.max(2, wanted);
    if (!isNum(raw) || raw <= 0) return 0;
    var magnitude = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var normal = raw / magnitude;
    var step = normal <= 1 ? 1 : (normal <= 2 ? 2 : (normal <= 5 ? 5 : 10));
    return step * magnitude;
  }

  function tickText(value, step) {
    if (Math.abs(value) < step * 1e-6) return '0';
    var abs = Math.abs(value);
    if (abs >= 1e6 || abs < 1e-5) {
      return value.toExponential(1).replace(/\.0e/, 'e').replace('e+', 'e').replace('-', '\u2212');
    }
    var decimals = step >= 1 ? 0 : Math.min(6, Math.ceil(-Math.log(step) / Math.LN10));
    var text = value.toFixed(decimals);
    if (decimals > 0) text = text.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '');
    return text.replace('-', '\u2212');
  }

/* ---------------- measure / draw ---------------- */

function measure() {
  var w = Math.round(canvas.clientWidth);
  var h = Math.round(canvas.clientHeight);
  var dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
  if (!w || !h) return false;
  if (w === size.w && h === size.h && dpr === size.dpr) return true;
  size = { w: w, h: h, dpr: dpr };
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  layer.width = canvas.width;
  layer.height = canvas.height;
  return true;
}

function drawStatic() {
  var w = size.w;
  var h = size.h;
  if (!w || !h) return;
  lctx.setTransform(size.dpr, 0, 0, size.dpr, 0, 0);
  lctx.clearRect(0, 0, w, h);
  lctx.fillStyle = '#0b1211';
  lctx.fillRect(0, 0, w, h);
  drawGrid(lctx, w, h);
  for (var i = 0; i < curves.length; i += 1) drawCurve(lctx, curves[i], w, h);
  drawEmptyHint(lctx, w, h);
}

function drawGrid(g, w, h) {
  var xstep = niceStep(view.xmax - view.xmin, w < 460 ? 4 : Math.max(4, Math.round(w / 96)));
  var ystep = niceStep(view.ymax - view.ymin, h < 260 ? 3 : Math.max(3, Math.round(h / 62)));
  if (!xstep || !ystep) return;

  var i, x, y, px, py;

  g.lineWidth = 1;
  g.font = '11px ' + MONO;
  g.textBaseline = 'middle';

  g.strokeStyle = 'rgba(240,234,221,0.075)';
  g.beginPath();
  for (i = 0, x = Math.ceil(view.xmin / xstep) * xstep; i < 200 && x <= view.xmax; i += 1, x += xstep) {
    px = Math.round(pxOfX(x)) + 0.5;
    if (px < 0 || px > w) continue;
    g.moveTo(px, 0);
    g.lineTo(px, h);
  }
  for (i = 0, y = Math.ceil(view.ymin / ystep) * ystep; i < 200 && y <= view.ymax; i += 1, y += ystep) {
    py = Math.round(pxOfY(y)) + 0.5;
    if (py < 0 || py > h) continue;
    g.moveTo(0, py);
    g.lineTo(w, py);
  }
  g.stroke();

  /* axes at zero, when zero is inside the window */
  g.strokeStyle = 'rgba(240,234,221,0.30)';
  g.beginPath();
  if (view.ymin <= 0 && view.ymax >= 0) {
    py = Math.round(pxOfY(0)) + 0.5;
    g.moveTo(0, py);
    g.lineTo(w, py);
  }
  if (view.xmin <= 0 && view.xmax >= 0) {
    px = Math.round(pxOfX(0)) + 0.5;
    g.moveTo(px, 0);
    g.lineTo(px, h);
  }
  g.stroke();

  /* tick labels: under the x axis (or the near edge), beside the y axis */
  var labelY;
  if (view.ymin <= 0 && view.ymax >= 0) labelY = clamp(pxOfY(0) + 13, 10, h - 6);
  else if (view.ymin > 0) labelY = h - 8;
  else labelY = 12;

  g.fillStyle = 'rgba(240,234,221,0.62)';
  g.textAlign = 'center';
  for (i = 0, x = Math.ceil(view.xmin / xstep) * xstep; i < 200 && x <= view.xmax; i += 1, x += xstep) {
    px = pxOfX(x);
    if (px < 16 || px > w - 16) continue;
    if (Math.abs(x) < xstep * 0.5) continue;
    g.fillText(tickText(x, xstep), px, labelY);
  }

  var labelX;
  var align;
  if (view.xmin <= 0 && view.xmax >= 0) {
    var axisPx = pxOfX(0);
    if (axisPx > w - 52) { labelX = axisPx - 7; align = 'right'; }
    else { labelX = Math.max(4, axisPx + 7); align = 'left'; }
  } else if (view.xmin > 0) {
    labelX = 5;
    align = 'left';
  } else {
    labelX = w - 5;
    align = 'right';
  }

  g.textAlign = align;
  for (i = 0, y = Math.ceil(view.ymin / ystep) * ystep; i < 200 && y <= view.ymax; i += 1, y += ystep) {
    py = pxOfY(y);
    if (py < 8 || py > h - 8) continue;
    if (Math.abs(y) < ystep * 0.5) continue;
    g.fillText(tickText(y, ystep), labelX, py);
  }

  /* a single origin zero when both axes are in the window */
  if (view.ymin <= 0 && view.ymax >= 0 && view.xmin <= 0 && view.xmax >= 0) {
    g.textAlign = 'right';
    g.fillText('0', clamp(pxOfX(0) - 6, 6, w - 6), clamp(pxOfY(0) + 13, 10, h - 6));
  }
}

function drawCurve(g, curve, w, h) {
  var points = curve.points;
  if (!points || !points.length) return;
  var limit = (view.ymax - view.ymin) * 4;
  var pad = h * 4;

  g.save();
  g.beginPath();
  g.rect(0, 0, w, h);
  g.clip();
  g.strokeStyle = curve.color;
  g.lineWidth = 2;
  g.lineJoin = 'round';
  g.lineCap = 'round';
  g.beginPath();

  var drawing = false;
  var prev = null;
  for (var i = 0; i < points.length; i += 1) {
    var point = points[i];
    if (!point) { drawing = false; prev = null; continue; }
    var px = pxOfX(point.x);
    var py = pxOfY(point.y);
    if (!isNum(px) || !isNum(py)) { drawing = false; prev = null; continue; }
    px = clamp(px, -pad, w + pad);
    py = clamp(py, -pad, h + pad);

    /* a jump between two points that are both off-screen is an
       asymptote, not a line: break the path instead of drawing it */
    if (prev && Math.abs(point.y - prev.y) > limit &&
        ((point.y > view.ymax && prev.y > view.ymax) ||
         (point.y < view.ymin && prev.y < view.ymin))) {
      drawing = false;
    }

    if (drawing) g.lineTo(px, py);
    else { g.moveTo(px, py); drawing = true; }
    prev = point;
  }
  g.stroke();
  g.restore();
}

function hasVisibleExpression() {
  for (var i = 0; i < curves.length; i += 1) {
    if (curves[i].visible && curves[i].state === 'ok') return true;
  }
  return false;
}

function drawEmptyHint(g, w, h) {
  for (var i = 0; i < curves.length; i += 1) {
    if (curves[i].points && curves[i].points.length) return;
  }
  g.save();
  g.fillStyle = 'rgba(240,234,221,0.60)';
  g.font = '12px ' + MONO;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  var message = hasVisibleExpression()
    ? 'no real values in this window'
    : 'every curve is hidden \u2014 use the eye buttons';
  g.fillText(message, w / 2, h / 2);
  g.restore();
}

function drawForeground() {
  if (!size.w || !size.h) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (layer.width) ctx.drawImage(layer, 0, 0);
  ctx.setTransform(size.dpr, 0, 0, size.dpr, 0, 0);
  drawHover();
}

function drawHover() {
  if (!hover) return;
  var w = size.w;
  var h = size.h;
  var cx = clamp(hover.cx, 0, w);
  var cy = clamp(hover.cy, 0, h);
  var x = xAt(cx);
  var px = Math.round(pxOfX(x)) + 0.5;

  ctx.save();
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.strokeStyle = 'rgba(240,234,221,0.40)';
  ctx.beginPath();
  ctx.moveTo(px, 0);
  ctx.lineTo(px, h);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(240,234,221,0.16)';
  ctx.beginPath();
  ctx.moveTo(0, Math.round(cy) + 0.5);
  ctx.lineTo(w, Math.round(cy) + 0.5);
  ctx.stroke();
  ctx.setLineDash([]);

  for (var i = 0; i < curves.length; i += 1) {
    var curve = curves[i];
    if (!curve.visible || curve.state !== 'ok') continue;
    var result = Engine.evaluate(curve.src, { angle: 'rad', scope: { x: x } });
    if (!result.ok || !isNum(result.value)) continue;
    var py = pxOfY(result.value);
    if (py < -8 || py > h + 8) continue;
    ctx.beginPath();
    ctx.arc(px, py, 4, 0, Math.PI * 2);
    ctx.fillStyle = curve.color;
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#0b1211';
    ctx.stroke();
  }

  /* x value tag riding the crosshair */
  var label = 'x ' + display(x);
  ctx.font = '11px ' + MONO;
  var width = ctx.measureText(label).width + 12;
  var bx = clamp(px - width / 2, 3, w - width - 3);
  ctx.fillStyle = 'rgba(11,18,17,0.88)';
  ctx.strokeStyle = 'rgba(240,234,221,0.22)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.rect(bx, 6, width, 20);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'rgba(240,234,221,0.85)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, bx + width / 2, 16);
  ctx.restore();
}

/* ---------------- trace strip, meta, fields ---------------- */

function renderTrace() {
  if (!traceXEl) return;
  if (!hover) {
    traceXEl.textContent = hasVisibleExpression()
      ? 'trace \u00b7 move the pointer across the plot'
      : 'trace \u00b7 no visible curves';
    if (traceListEl) traceListEl.textContent = '';
    return;
  }

  var x = xAt(clamp(hover.cx, 0, size.w));
  traceXEl.textContent = 'x = ' + display(x);
  if (!traceListEl) return;
  traceListEl.textContent = '';

  for (var i = 0; i < curves.length; i += 1) {
    var curve = curves[i];
    if (!curve.visible || curve.state !== 'ok') continue;
    var result = Engine.evaluate(curve.src, { angle: 'rad', scope: { x: x } });

    var item = document.createElement('li');
    item.className = 'gtrace__item';

    var dot = document.createElement('span');
    dot.className = 'gtrace__dot';
    dot.style.background = curve.color;

    var key = document.createElement('span');
    key.className = 'gtrace__key';
    key.textContent = curve.tag;

    var value = document.createElement('span');
    value.textContent = (result.ok && isNum(result.value)) ? display(result.value) : '\u2014';

    item.appendChild(dot);
    item.appendChild(key);
    item.appendChild(value);
    traceListEl.appendChild(item);
  }
}

function syncMeta() {
  if (metaEl) {
    metaEl.textContent = 'window ' + shortText(view.xmin) + ' \u2026 ' + shortText(view.xmax) +
      ' by ' + shortText(view.ymin) + ' \u2026 ' + shortText(view.ymax);
  }
  var shown = 0;
  for (var i = 0; i < curves.length; i += 1) {
    if (curves[i].visible && curves[i].state === 'ok') shown += 1;
  }
  if (capEl) {
    capEl.textContent = shown === 0 ? 'no curves' : (shown === 1 ? '1 curve' : shown + ' curves');
  }
  if (canvas) {
    canvas.setAttribute('aria-label',
      'Plot window: x from ' + shortText(view.xmin) + ' to ' + shortText(view.xmax) +
      ', y from ' + shortText(view.ymin) + ' to ' + shortText(view.ymax) + '. ' +
      (shown === 1 ? '1 curve shown.' : shown + ' curves shown.'));
  }
}

function syncFields(mode) {
  if (!fieldEls.xmin) return;
  if (mode !== 'skip') {
    fieldEls.xmin.value = numText(view.xmin);
    fieldEls.xmax.value = numText(view.xmax);
  }
  if (autoY || mode !== 'skip') {
    fieldEls.ymin.value = numText(view.ymin);
    fieldEls.ymax.value = numText(view.ymax);
  }
  fieldEls.ymin.disabled = autoY;
  fieldEls.ymax.disabled = autoY;
}

function setViewMessage(message) {
  if (viewMsgEl) viewMsgEl.textContent = message || '';
}

/* ---------------- refresh pipeline ---------------- */

function refresh(options) {
  var opts = options || {};
  if (opts.revalidate) validateAll();
  if (!measure()) {
    syncFields(opts.fields || 'all');
    syncMeta();
    return;
  }
  prepare();
  syncFields(opts.fields || 'all');
  syncMeta();
  drawStatic();
  drawForeground();
  renderTrace();
}

/* ---------------- view control ---------------- */

function cleanView(candidate) {
  var keys = ['xmin', 'xmax', 'ymin', 'ymax'];
  var next = {};
  for (var i = 0; i < keys.length; i += 1) {
    var value = candidate[keys[i]];
    if (!isNum(value)) return null;
    next[keys[i]] = value;
  }
  var spanX = next.xmax - next.xmin;
  var spanY = next.ymax - next.ymin;
  if (spanX <= 0 || spanY <= 0) return null;
  if (spanX < MIN_SPAN || spanY < MIN_SPAN) return null;
  if (spanX > MAX_SPAN || spanY > MAX_SPAN) return null;
  return next;
}

function zoomBy(factor, anchor) {
  if (!isNum(factor) || factor <= 0 || !size.w) return;
  var cx = anchor ? clamp(anchor.cx, 0, size.w) : size.w / 2;
  var cy = anchor ? clamp(anchor.cy, 0, size.h) : size.h / 2;
  var ax = xAt(cx);
  var ay = yAt(cy);

  var next = {
    xmin: ax - (ax - view.xmin) * factor,
    xmax: ax + (view.xmax - ax) * factor,
    ymin: autoY ? view.ymin : ay - (ay - view.ymin) * factor,
    ymax: autoY ? view.ymax : ay + (view.ymax - ay) * factor
  };

  var spanX = next.xmax - next.xmin;
  var spanY = next.ymax - next.ymin;
  if (!isNum(spanX) || !isNum(spanY)) return;
  if (spanX < MIN_SPAN || spanX > MAX_SPAN) {
    setViewMessage('that is as far as this plot will zoom');
    return;
  }
  if (!autoY && (spanY < MIN_SPAN || spanY > MAX_SPAN)) return;

  var cleaned = cleanView(next);
  if (!cleaned) return;
  setViewMessage('');
  view = cleaned;
  hover = null;
  refresh();
}

function resetView() {
  view = { xmin: HOME.xmin, xmax: HOME.xmax, ymin: HOME.ymin, ymax: HOME.ymax };
  autoY = true;
  if (autoBox) autoBox.checked = true;
  hover = null;
  drag = null;
  setViewMessage('');
  if (canvas) canvas.classList.remove('is-dragging');
  refresh({ revalidate: true });
}

function setAutoY(on) {
  autoY = !!on;
  if (autoBox) autoBox.checked = autoY;
  setViewMessage('');
  refresh();
}

function readField(el) {
  if (!el) return NaN;
  var raw = String(el.value).replace(/\u2212/g, '-').replace(/,/g, '').trim();
  if (!raw) return NaN;
  var value = Number(raw);
  return isNum(value) ? value : NaN;
}

function applyFields() {
  var next = {
    xmin: readField(fieldEls.xmin),
    xmax: readField(fieldEls.xmax),
    ymin: readField(fieldEls.ymin),
    ymax: readField(fieldEls.ymax)
  };

  var problem = '';
  if (!isNum(next.xmin) || !isNum(next.xmax)) problem = 'x min and x max need numbers';
  else if (!isNum(next.ymin) || !isNum(next.ymax)) problem = 'y min and y max need numbers';
  else if (next.xmax <= next.xmin) problem = 'x max must be larger than x min';
  else if (!autoY && next.ymax <= next.ymin) problem = 'y max must be larger than y min';
  else if (next.xmax - next.xmin < MIN_SPAN) problem = 'that x window is too small to plot';
  else if (next.xmax - next.xmin > MAX_SPAN) problem = 'that x window is too large to plot';
  else if (!autoY && next.ymax - next.ymin < MIN_SPAN) problem = 'that y window is too small to plot';
  else if (!autoY && next.ymax - next.ymin > MAX_SPAN) problem = 'that y window is too large to plot';

  if (problem) { setViewMessage(problem); return false; }

  if (autoY) { next.ymin = view.ymin; next.ymax = view.ymax; }
  setViewMessage('');
  view = { xmin: next.xmin, xmax: next.xmax, ymin: next.ymin, ymax: next.ymax };
  hover = null;
  refresh({ fields: 'skip' });
  return true;
}

  /* ---------------- pointer, wheel, keys ---------------- */

  function pointerAnchor(event) {
    var rect = canvas.getBoundingClientRect();
    return { cx: event.clientX - rect.left, cy: event.clientY - rect.top };
  }

  function onPointerDown(event) {
    if (!size.w) return;
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    if (canvas.setPointerCapture) {
      try { canvas.setPointerCapture(event.pointerId); } catch (error) { /* ignore */ }
    }
    drag = {
      id: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      view: { xmin: view.xmin, xmax: view.xmax, ymin: view.ymin, ymax: view.ymax },
      moved: false
    };
    canvas.classList.add('is-dragging');
    hover = null;
    renderTrace();
    drawForeground();
    event.preventDefault();
  }

  function onPointerMove(event) {
    if (!size.w) return;

    if (drag && drag.id === event.pointerId) {
      var dx = event.clientX - drag.x;
      var dy = event.clientY - drag.y;
      if (!drag.moved && Math.abs(dx) + Math.abs(dy) > 5) {
        drag.moved = true;
        if (autoY && Math.abs(dy) > 8) setAutoY(false);
      }
      if (drag.moved) {
        var spanX = drag.view.xmax - drag.view.xmin;
        var spanY = drag.view.ymax - drag.view.ymin;
        var shiftX = dx * spanX / size.w;
        var shiftY = dy * spanY / size.h;
        var next = {
          xmin: drag.view.xmin - shiftX,
          xmax: drag.view.xmax - shiftX,
          ymin: autoY ? view.ymin : drag.view.ymin + shiftY,
          ymax: autoY ? view.ymax : drag.view.ymax + shiftY
        };
        var cleaned = cleanView(next);
        if (cleaned) {
          view = cleaned;
          setViewMessage('');
          refresh({ fields: 'all' });
        }
      }
      return;
    }

    if (event.pointerType === 'touch') return;
    hover = pointerAnchor(event);
    renderTrace();
    drawForeground();
  }

  function onPointerUp(event) {
    if (!drag || drag.id !== event.pointerId) return;
    var moved = drag.moved;
    drag = null;
    canvas.classList.remove('is-dragging');
    if (canvas.releasePointerCapture) {
      try { canvas.releasePointerCapture(event.pointerId); } catch (error) { /* ignore */ }
    }
    if (!moved) {
      hover = pointerAnchor(event);
      renderTrace();
      drawForeground();
    }
    event.preventDefault();
  }

  function onPointerLeave() {
    if (drag || !hover) return;
    hover = null;
    renderTrace();
    drawForeground();
  }

  function onWheel(event) {
    if (!size.w) return;
    event.preventDefault();
    var delta = event.deltaY;
    if (event.deltaMode === 1) delta *= 16;
    else if (event.deltaMode === 2) delta *= size.h;
    var factor = Math.exp(clamp(delta, -120, 120) * 0.0018);
    zoomBy(factor, pointerAnchor(event));
  }

  function onKeyDown(event) {
    var key = event.key;
    if (typeof key !== 'string' || event.ctrlKey || event.metaKey || event.altKey) return;
    if (!size.w) return;

    if (key === 'ArrowLeft' || key === 'ArrowRight' || key === 'ArrowUp' || key === 'ArrowDown') {
      event.preventDefault();
      var stepX = (view.xmax - view.xmin) * 0.1;
      var stepY = (view.ymax - view.ymin) * 0.1;
      var dx = key === 'ArrowLeft' ? -stepX : (key === 'ArrowRight' ? stepX : 0);
      var dy = key === 'ArrowUp' ? stepY : (key === 'ArrowDown' ? -stepY : 0);
      if (dy && autoY) setAutoY(false);
      var next = {
        xmin: view.xmin + dx,
        xmax: view.xmax + dx,
        ymin: autoY ? view.ymin : view.ymin + dy,
        ymax: autoY ? view.ymax : view.ymax + dy
      };
      var cleaned = cleanView(next);
      if (cleaned) {
        view = cleaned;
        hover = null;
        refresh();
      }
      return;
    }

    if (key === '+' || key === '=') { event.preventDefault(); zoomBy(0.8, null); return; }
    if (key === '-' || key === '_') { event.preventDefault(); zoomBy(1.25, null); return; }
    if (key === '0' || key === 'Home') { event.preventDefault(); resetView(); }
  }

  /* ---------------- expression, eye and field wiring ---------------- */

  function scheduleRefresh() {
    if (exprTimer) window.clearTimeout(exprTimer);
    exprTimer = window.setTimeout(function () {
      exprTimer = null;
      refresh({ revalidate: true });
    }, 120);
  }

  for (var c = 0; c < curves.length; c += 1) {
    (function (curve) {
      if (curve.input) {
        curve.input.addEventListener('input', function () {
          var text = curve.input.value;
          if (text !== curve.src) {
            curve.src = text;
            if (!curve.visible && text.replace(/\s+/g, '')) {
              curve.visible = true;
              renderRow(curve);
            }
          }
          scheduleRefresh();
        });
        curve.input.addEventListener('keydown', function (event) {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          if (exprTimer) { window.clearTimeout(exprTimer); exprTimer = null; }
          refresh({ revalidate: true });
        });
      }
      if (curve.eye) {
        curve.eye.addEventListener('click', function () {
          curve.visible = !curve.visible;
          if (curve.input) curve.src = curve.input.value;
          renderRow(curve);
          refresh({ revalidate: true });
        });
      }
    })(curves[c]);
  }

  if (autoBox) {
    autoBox.addEventListener('change', function () { setAutoY(autoBox.checked); });
  }

  ['xmin', 'xmax', 'ymin', 'ymax'].forEach(function (key) {
    var el = fieldEls[key];
    if (!el) return;
    el.addEventListener('input', function () {
      if (fieldTimer) window.clearTimeout(fieldTimer);
      fieldTimer = window.setTimeout(function () {
        fieldTimer = null;
        applyFields();
      }, 180);
    });
    el.addEventListener('change', function () {
      if (fieldTimer) { window.clearTimeout(fieldTimer); fieldTimer = null; }
      if (applyFields()) syncFields('all');
    });
    el.addEventListener('keydown', function (event) {
      if (event.key !== 'Enter') return;
      event.preventDefault();
      if (fieldTimer) { window.clearTimeout(fieldTimer); fieldTimer = null; }
      if (applyFields()) syncFields('all');
    });
  });

  if (zoomInBtn) zoomInBtn.addEventListener('click', function () { zoomBy(0.8, null); });
  if (zoomOutBtn) zoomOutBtn.addEventListener('click', function () { zoomBy(1.25, null); });
  if (resetBtn) resetBtn.addEventListener('click', function () { resetView(); });

  canvas.addEventListener('pointerdown', onPointerDown);
  canvas.addEventListener('pointermove', onPointerMove);
  canvas.addEventListener('pointerup', onPointerUp);
  canvas.addEventListener('pointercancel', onPointerUp);
  canvas.addEventListener('pointerleave', onPointerLeave);
  canvas.addEventListener('wheel', onWheel, { passive: false });
  canvas.addEventListener('keydown', onKeyDown);
  canvas.addEventListener('dblclick', function (event) {
    if (event.button !== 0) return;
    zoomBy(0.7, pointerAnchor(event));
  });

  /* ---------------- resize and mode switch ---------------- */

  function onResize() {
    if (resizeQueued) return;
    resizeQueued = true;
    window.requestAnimationFrame(function () {
      resizeQueued = false;
      if (!canvas.clientWidth) return;   /* hidden: the mode switch re-measures */
      size = { w: 0, h: 0, dpr: 0 };
      refresh();
    });
  }

  if (window.ResizeObserver) {
    var observer = new ResizeObserver(onResize);
    observer.observe(canvas);
  }
  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', onResize);

  document.addEventListener('fluxion:modechange', function (event) {
    if (!event.detail || event.detail.mode !== 'graph') return;
    window.requestAnimationFrame(function () {
      size = { w: 0, h: 0, dpr: 0 };
      refresh({ revalidate: true });
    });
  });

  /* ---------------- first paint ---------------- */

  (function init() {
    for (var i = 0; i < curves.length; i += 1) {
      if (curves[i].input) curves[i].src = curves[i].input.value;
      renderRow(curves[i]);
    }
    if (autoBox) autoBox.checked = autoY;
    syncFields('all');
    syncMeta();
    if (document.body.getAttribute('data-mode') === 'graph') {
      refresh({ revalidate: true });
    } else {
      validateAll();
    }
  })();
})();

