import sys
from playwright.sync_api import sync_playwright

URL = "file:///home/user/project/preview.html"

ASCII = """(cols) => {
  const c = document.getElementById('graph-canvas');
  const g = c.getContext('2d', {willReadFrequently: true});
  const d = g.getImageData(0, 0, c.width, c.height).data;
  const W = c.width, H = c.height, col = cols, row = Math.round(cols * H / W / 2.1);
  const rows = [];
  const ch = (r, gr, b) => {
    if (Math.abs(r-242) < 30 && Math.abs(gr-180) < 30 && Math.abs(b-87) < 30) return '1';
    if (Math.abs(r-79) < 30 && Math.abs(gr-209) < 30 && Math.abs(b-217) < 30) return '2';
    if (Math.abs(r-183) < 30 && Math.abs(gr-155) < 30 && Math.abs(b-246) < 30) return '3';
    const lum = (r + gr + b) / 3;
    if (lum > 60) return '#';
    if (lum > 24) return '+';
    if (lum > 14) return '.';
    return ' ';
  };
  for (let y = 0; y < row; y++) {
    let line = '';
    for (let x = 0; x < col; x++) {
      const px = Math.floor((x + 0.5) * W / col);
      const py = Math.floor((y + 0.5) * H / row);
      const i = ((py * W) + px) * 4;
      line += ch(d[i], d[i+1], d[i+2]);
    }
    rows.push(line);
  }
  return rows.join('\\n');
}"""

with sync_playwright() as p:
    b = p.chromium.launch(headless=True)
    pg = b.new_page(viewport={"width": 1280, "height": 1100})
