LABELS = """() => {
  const c = document.getElementById('graph-canvas');
  const g = c.getContext('2d', {willReadFrequently: true});
  const d = g.getImageData(0, 0, c.width, c.height).data;
  const W = c.width, H = c.height;
  let bright = 0, bandLow = 0, bandHigh = 0;
  const cols = new Set();
  let axisRow = -1, axisCount = 0;
  for (let y = 0; y < H; y++) {
    let rowBright = 0;
    for (let x = 0; x < W; x++) {
      const i = ((y * W) + x) * 4;
      const r = d[i], gg = d[i + 1], b = d[i + 2];
      const colored = Math.abs(r-242) < 30 && Math.abs(gg-180) < 30 && Math.abs(b-87) < 30;
      const lum = (r + gg + b) / 3;
      if (!colored && lum > 110) { bright++; rowBright++; cols.add(Math.round(x / 10)); }
    }
    if (rowBright > axisCount) { axisCount = rowBright; axisRow = y; }
  }
  return { bright, axisRow, axisRowBright: axisCount, W, H, labelColumns: cols.size };
}"""

CONTRAST = """() => {
  const lum = (hex) => {
    const m = hex.match(/[0-9a-f]{2}/gi).map(h => parseInt(h, 16) / 255);
    const f = m.map(v => v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
    return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2];
  };
  const ratio = (a, b) => { const l1 = lum(a), l2 = lum(b); const [hi, lo] = l1 > l2 ? [l1, l2] : [l2, l1]; return (hi + 0.05) / (lo + 0.05); };
  const pairs = [
    ['gfun__title', '.gfun__title', '.panel'],
    ['gfun__note', '.gfun__note', '.panel'],
    ['gfn__tag', '.gfn__tag', '.gfn'],
    ['gfn__input', '.gfn__input', '.gfn'],
    ['gbtn--text', '.gbtn--text', '.gbtn'],
    ['ghint', '.ghint', '.panel'],
    ['gtrace__x', '.gtrace__x', '.gtrace'],
    ['gtrace__key', '.gtrace__key', '.gtrace'],
    ['gview__msg', '.gview__msg', '.gview'],
    ['field__label', '#graph-view .field__label', '.gview'],
    ['gcheck__text', '.gcheck__text', '.gview'],
    ['traceValue', '.gtrace__item', '.gtrace'],
    ['offRowTag', '#graph-list .gfn.is-off .gfn__tag', '#graph-list .gfn.is-off']
  ];
  const bg = (el) => {
    let node = el, stack = [];
    while (node && node !== document.documentElement) {
      const c = getComputedStyle(node).backgroundColor;
      if (c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent') { stack.push(c); break; }
      node = node.parentElement;
    }
    return stack[0] || 'rgb(10,15,15)';
  };
  const toHex = (rgb) => {
    const m = rgb.match(/\\d+/g);
    if (!m) return '000000';
    return m.slice(0, 3).map(v => (+v).toString(16).padStart(2, '0')).join('');
  };
  const out = [];
  for (const [name, sel, bgsel] of pairs) {
    const el = document.querySelector(sel);
    if (!el) { out.push([name, 'missing']); continue; }
    const fg = getComputedStyle(el).color;
    const bgel = bgsel ? document.querySelector(bgsel) : el;
    out.push([name, Math.round(ratio(toHex(fg), toHex(bg(bgel || el))) * 10) / 10, toHex(fg), toHex(bg(bgel || el))]);
  }
  return out;
}"""

