      if (!neutral(i)) continue;
      rows[y] = (rows[y]||0)+1;
      cols[x] = (cols[x]||0)+1;
    }
  }
  const top = (obj, n) => Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,n).map(([k,v])=>[Math.round(k/dpr), v]);
