CLUSTERS = """() => {
  const c = document.getElementById('graph-canvas');
  const g = c.getContext('2d', {willReadFrequently: true});
  const dpr = c.width / c.clientWidth;
  const d = g.getImageData(0, 0, c.width, c.height).data;
  const W = c.width, H = c.height;
  const neutral = (i) => {
    const r = d[i], gg = d[i+1], b = d[i+2];
    const lum = (r + gg + b) / 3;
    return lum > 110 && Math.abs(r-gg) < 14 && Math.abs(gg-b) < 14;
  };
  // x tick labels: neutral bright pixels in the band 12..30 px below the axis row
  const axisRow = window.__axisRow;
  const bandTop = axisRow + 4, bandBottom = axisRow + 34;
  const hit = new Set();
  for (let y = bandTop; y < bandBottom && y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = ((y*W)+x)*4;
      if (neutral(i)) hit.add(x);
    }
  }
  const xs = Array.from(hit).sort((a,b)=>a-b);
  const groups = [];
  let start = null, prev = null;
  for (const x of xs) {
    if (start === null) { start = x; prev = x; continue; }
    if (x - prev > 6 * dpr) { groups.push([Math.round(start/dpr), Math.round(prev/dpr)]); start = x; }
    prev = x;
  }
  if (start !== null) groups.push([Math.round(start/dpr), Math.round(prev/dpr)]);
  return { groups, axisRow: Math.round(axisRow/dpr) };
}"""

