/* ------------------------------------------------------------------
   Date mode (task 4). The violet accent comes from body[data-mode="date"];
   everything here reuses the shell tokens, .field, .readout, .data-list
   and .chip primitives. Only the date-specific layout is new.
------------------------------------------------------------------- */

.date-inputs {
  display: grid;
  gap: var(--s3);
}

.date-inputs__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--s2);
}

.date-inputs__title {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
}

/* preset intervals: chip-shaped buttons, not decorative chips */
.date-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.date-preset {
  appearance: none;
  cursor: pointer;
  padding: 3px 9px;
  border: 1px solid var(--hair-strong);
  border-radius: 999px;
  background: transparent;
  color: var(--mist);
  font-family: var(--mono);
  font-size: 0.6875rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.015em;
  transition: color 130ms ease, border-color 130ms ease, background-color 130ms ease;
}
.date-preset:hover {
  color: var(--bone);
  border-color: var(--accent-line);
  background: var(--accent-soft);
}
.date-preset:active { transform: translateY(1px); }
.date-preset.is-on {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent);
}

/* chips inside the readout foot */
.date-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.date-msg { margin-top: -2px; }
.date-msg--warn { color: var(--accent); }
.date-msg--warn::before { content: "! "; font-weight: 600; }

/* timeline --------------------------------------------------------- */

.timeline {
  display: grid;
  gap: 0;
  padding: var(--s2) var(--s3) 0;
}

.timeline__cap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 5px var(--s3);
  margin-top: 2px;
  padding: 6px 0 8px;
  border-top: 1px solid var(--hair);
}

.timeline__keys {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s3);
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--dim);
}

.tl-key { display: inline-flex; align-items: center; gap: 5px; }

.tl-mark {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
}
.tl-mark--from {
  border: 1.5px solid var(--accent);
  background: var(--screen);
}
.tl-mark--to { background: var(--accent); }
.tl-mark--today {
  width: 9px;
  height: 11px;
  border-radius: 0;
  border-left: 1.5px dashed var(--accent);
  background: transparent;
}

.timeline__scale {
  font-family: var(--mono);
  font-size: 0.625rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  color: var(--dim);
}

.timeline svg text { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.tl-text--pin { fill: var(--bone); font-size: 11px; }
.tl-text--name { fill: var(--dim); font-size: 10px; letter-spacing: 0.07em; }
.tl-text--now { fill: var(--accent); font-size: 10px; letter-spacing: 0.07em; }
.tl-text--tick { fill: var(--dim); font-size: 10px; }

/* interval note + cards -------------------------------------------- */

.date-note {
  font-family: var(--mono);
  font-size: 0.625rem;
  line-height: 1.65;
  color: var(--dim);
  max-width: 46ch;
}

.date-card {
  display: grid;
  gap: var(--s3);
  align-content: start;
  padding: var(--s4);
  border: 1px solid var(--hair);
  border-radius: var(--r);
  background: var(--screen);
}

.date-card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 2px var(--s3);
  padding-bottom: var(--s2);
  border-bottom: 1px solid var(--hair);
}

.date-card__title {
  font-family: var(--serif);
  font-weight: 400;
  font-size: 1rem;
  line-height: 1.3;
  color: var(--bone);
}

.date-card__meta {
  font-family: var(--mono);
  font-size: 0.625rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
  color: var(--dim);
  text-align: right;
}

.date-card .data-list { border-top: 0; }

/* shift a date ----------------------------------------------------- */

.date-shift__body {
  display: grid;
  gap: var(--s3);
  align-items: end;
}

.date-shift__row {
  display: grid;
  gap: var(--s3);
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 0.7fr) minmax(0, 0.85fr);
  align-items: end;
}

.date-shift__row .field { align-content: end; }

.shift-dir .seg__btn {
  padding: 11px 14px 12px;
  font-size: 0.875rem;
  min-width: 38px;
}

.field__select {
  appearance: none;
  -webkit-appearance: none;
  padding-right: 26px;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--mist) 50%),
    linear-gradient(135deg, var(--mist) 50%, transparent 50%);
  background-position:
    calc(100% - 13px) calc(50% + 1px),
    calc(100% - 9px) calc(50% + 1px);
  background-size: 4px 4px, 4px 4px;
  background-repeat: no-repeat;
}

.shift-out {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 3px var(--s3);
  min-height: 100%;
  padding: var(--s3);
  border: 1px solid var(--accent-line);
  border-radius: var(--r);
  background: var(--accent-soft);
}

.shift-out__date {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: clamp(1rem, 2.2vw, 1.25rem);
  line-height: 1.25;
  letter-spacing: -0.01em;
  color: var(--accent);
}

.shift-out__meta {
  font-family: var(--mono);
  font-size: 0.6875rem;
  font-variant-numeric: tabular-nums;
  color: var(--mist);
}

@media (min-width: 880px) {
  .date-shift__body {
    grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  }
}

@media (max-width: 879px) {
  .date-shift__row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .date-shift__row > .field:first-child { grid-column: 1 / -1; }
}

@media (max-width: 420px) {
  .date-shift__row { grid-template-columns: minmax(0, 1fr); }
  .date-shift__row > .field:first-child { grid-column: auto; }
  .date-card { padding: var(--s3); }
  .timeline { padding-left: var(--s2); padding-right: var(--s2); }
}

/* ==================================================================
   DATE MODE (task 4)
   Native Date only. Every calendar date is anchored at 12:00 UTC, so
   day arithmetic never drifts with DST or the host time zone.
   Difference, shift arithmetic, derived calendar facts, and an SVG
   timeline drawn to scale across from / to / today.
=================================================================== */
(function () {
  'use strict';

  var fromInput = document.getElementById('date-from');
  var toInput = document.getElementById('date-to');
  if (!fromInput || !toInput) return;

  var valueEl = document.getElementById('date-value');
  var unitEl = document.getElementById('date-unit');
  var exprEl = document.getElementById('date-expr');
  var chipsEl = document.getElementById('date-chips');
  var msgEl = document.getElementById('date-msg');
  var listEl = document.getElementById('date-list');
  var factsEl = document.getElementById('date-facts');
  var factsForEl = document.getElementById('date-facts-for');
  var metaEl = document.getElementById('date-meta');
  var timelineHost = document.getElementById('date-timeline');
  var timelineSvg = document.getElementById('date-timeline-svg');
  var scaleEl = document.getElementById('date-scale');
  var presetBtns = Array.prototype.slice.call(document.querySelectorAll('.date-preset'));

  var shiftInput = document.getElementById('shift-date');
  var shiftAmount = document.getElementById('shift-amount');
  var shiftUnit = document.getElementById('shift-unit');
  var shiftAdd = document.getElementById('shift-add');
  var shiftSub = document.getElementById('shift-sub');
  var shiftDateOut = document.getElementById('shift-date-out');
  var shiftMeta = document.getElementById('shift-meta');
  var shiftMsg = document.getElementById('shift-msg');
  var shiftDir = 1;

  var DAY_MS = 86400000;
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June',
                     'July', 'August', 'September', 'October', 'November', 'December'];
  var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var WEEKDAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  /* ---------------- UTC-safe date helpers ---------------- */

  function utc(y, m, d) {
    /* noon anchor: +/- an hour can never tip a day boundary */
    return new Date(Date.UTC(y, m - 1, d, 12, 0, 0, 0));
  }

  function parts(date) {
    return { y: date.getUTCFullYear(), m: date.getUTCMonth() + 1, d: date.getUTCDate() };
  }

  function todayDate() {
    var now = new Date();
    return utc(now.getFullYear(), now.getMonth() + 1, now.getDate());
  }

  function isLeap(y) {
    return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  }

  function daysInMonth(y, m) {
    return new Date(Date.UTC(y, m, 0, 12)).getUTCDate();
  }

  function daysInYear(y) {
    return isLeap(y) ? 366 : 365;
  }

  /* a stable integer per calendar day (noon rounds to the day index) */
  function serial(date) {
    return Math.round(date.getTime() / DAY_MS);
  }

  function fromSerial(n) {
    return new Date(n * DAY_MS - DAY_MS / 2);
  }

  function diffDays(a, b) {
    return serial(b) - serial(a);
  }

  function sameDay(a, b) {
    return serial(a) === serial(b);
  }

  function addDays(date, n) {
    return new Date(date.getTime() + n * DAY_MS);
  }

  /* month/year arithmetic saturates: 31 Jan + 1 month = 29/28 Feb */
  function addMonthsSat(date, n) {
    var p = parts(date);
    var total = p.y * 12 + (p.m - 1) + n;
    var y = Math.floor(total / 12);
    var m = total - y * 12 + 1;
    var d = Math.min(p.d, daysInMonth(y, m));
    return utc(y, m, d);
  }

  function addYearsSat(date, n) {
    return addMonthsSat(date, n * 12);
  }

  function inRange(date) {
    var y = parts(date).y;
    return y >= 1 && y <= 9999;
  }

  /* ---------------- parsing + formatting ---------------- */

  function parseInput(value) {
    if (!value) {
      return { ok: false, error: 'Choose a date in both fields.' };
    }
    var match = /^(\d{4,})-(\d{2})-(\d{2})$/.exec(String(value).trim());
    if (!match) {
      return { ok: false, error: 'Use the date picker or type YYYY-MM-DD.' };
    }
    var y = parseInt(match[1], 10);
    var m = parseInt(match[2], 10);
    var d = parseInt(match[3], 10);
    if (y < 1 || y > 9999) {
      return { ok: false, error: 'Years outside 1 to 9999 are not supported.' };
    }
    if (m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m)) {
      return { ok: false, error: 'That day does not exist in that month.' };
    }
    return { ok: true, date: utc(y, m, d) };
  }

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }
  function pad4(n) {
    var s = '' + n;
    while (s.length < 4) s = '0' + s;
    return s;
  }

  function isoValue(date) {
    var p = parts(date);
    return pad4(p.y) + '-' + pad2(p.m) + '-' + pad2(p.d);
  }

  function fmtShort(date) {
    var p = parts(date);
    return p.d + ' ' + MONTHS[p.m - 1] + ' ' + p.y;
  }

  function fmtCompact(date) {
    return WEEKDAYS_SHORT[date.getUTCDay()] + ' ' + fmtShort(date);
  }

  function fmtLong(date) {
    var p = parts(date);
    return WEEKDAYS[date.getUTCDay()] + ' ' + p.d + ' ' + MONTHS_LONG[p.m - 1] + ' ' + p.y;
  }

  function groupInt(n) {
    var s = String(Math.abs(n));
    return (n < 0 ? '−' : '') + s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function fmtTick(date, spanDays) {
    var p = parts(date);
    if (spanDays <= 200) return p.d + ' ' + MONTHS[p.m - 1];
    return MONTHS[p.m - 1] + ' ' + p.y;
  }

  function plural(n, unit) {
    return n + ' ' + (n === 1 ? unit.replace(/s$/, '') : unit);
  }

  function esc(text) {
    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  /* ---------------- calendar maths ---------------- */

  function ymdSpan(a, b) {
    /* both orders handled by the caller; here a <= b */
    var years = parts(b).y - parts(a).y;
    var anchor = addYearsSat(a, years);
    if (serial(anchor) > serial(b)) {
      years -= 1;
      anchor = addYearsSat(a, years);
    }
    var months = (parts(b).y * 12 + parts(b).m) - (parts(anchor).y * 12 + parts(anchor).m);
    var mid = addMonthsSat(anchor, months);
    if (serial(mid) > serial(b)) {
      months -= 1;
      mid = addMonthsSat(anchor, months);
    }
    return { years: years, months: months, days: diffDays(mid, b) };
  }

  /* weekdays in [a, b): Monday to Friday, Saturday and Sunday excluded */
  function weekdaysBetween(a, b) {
    var n = diffDays(a, b);
    if (n <= 0) return 0;
    var whole = Math.floor(n / 7);
    var count = whole * 5;
    var rest = n % 7;
    var dow = a.getUTCDay();
    for (var i = 0; i < rest; i += 1) {
      var w = (dow + i) % 7;
      if (w !== 0 && w !== 6) count += 1;
    }
    return count;
  }

  function leapDayBetween(a, b) {
    var y = parts(a).y;
    var last = parts(b).y;
    var start = serial(a);
    var end = serial(b);
    for (; y <= last; y += 1) {
      if (!isLeap(y)) continue;
      var leap = utc(y, 2, 29);
      var s = serial(leap);
      if (s >= start && s < end) return leap;
    }
    return null;
  }

  function isoWeek(date) {
    var p = parts(date);
    var d = new Date(Date.UTC(p.y, p.m - 1, p.d, 12));
    var dow = (d.getUTCDay() + 6) % 7;          /* Monday = 0 */
    d.setUTCDate(d.getUTCDate() - dow + 3);      /* Thursday of this ISO week */
    var isoYear = d.getUTCFullYear();
    var jan4 = new Date(Date.UTC(isoYear, 0, 4, 12));
    var jan4Dow = (jan4.getUTCDay() + 6) % 7;
    jan4.setUTCDate(jan4.getUTCDate() - jan4Dow + 3);
    var week = 1 + Math.round((d.getTime() - jan4.getTime()) / (7 * DAY_MS));
    return { week: week, year: isoYear };
  }

  function dayOfYear(date) {
    return diffDays(utc(parts(date).y, 1, 1), date) + 1;
  }

  /* ---------------- DOM helpers ---------------- */

  function clear(el) {
    while (el && el.firstChild) el.removeChild(el.firstChild);
  }

  function row(label, value) {
    var r = document.createElement('div');
    r.className = 'data-list__row';
    var l = document.createElement('span');
    l.className = 'data-list__label';
    l.textContent = label;
    var v = document.createElement('span');
    v.className = 'data-list__value';
    v.textContent = value;
    r.appendChild(l);
    r.appendChild(v);
    return r;
  }

  function setMessage(el, text, kind) {
    el.textContent = text || '';
    el.className = 'sci-msg date-msg' + (kind ? ' ' + kind : '');
  }

  function chip(text, accent) {
    var s = document.createElement('span');
    s.className = 'chip' + (accent ? ' chip--accent' : '');
    s.textContent = text;
    return s;
  }

  function placeholderRows(target, labels) {
    clear(target);
    for (var i = 0; i < labels.length; i += 1) target.appendChild(row(labels[i], '—'));
  }

  /* ---------------- interval readout ---------------- */

  var DASH_ROWS = [
    'Calendar span',
    'Total days',
    'Weeks',
    'Business days · Mon–Fri',
    'Weekend days',
    'Both endpoints',
    'Leap day inside'
  ];

  function renderInterval(from, to, today) {
    clear(chipsEl);

    if (!from.ok || !to.ok) {
      exprEl.textContent = (from.ok ? fmtShort(from.date) : '—') + ' → ' +
                           (to.ok ? fmtShort(to.date) : '—');
      valueEl.className = 'readout__value is-preview';
      valueEl.textContent = '—';
      unitEl.textContent = 'days';
      setMessage(msgEl, !from.ok ? from.error : to.error, 'sci-msg--error');
      placeholderRows(listEl, DASH_ROWS);
      return;
    }

    var reversed = serial(to.date) < serial(from.date);
    var a = reversed ? to.date : from.date;
    var b = reversed ? from.date : to.date;
    var total = diffDays(a, b);
    var span = ymdSpan(a, b);
    var business = weekdaysBetween(a, b);
    var weekend = total - business;
    var leap = leapDayBetween(a, b);

    exprEl.textContent = fmtShort(from.date) + ' → ' + fmtShort(to.date) +
                         (reversed ? ' · end before start' : '');

    valueEl.className = 'readout__value';
    valueEl.textContent = (reversed && total ? '−' : '') + groupInt(total);
    unitEl.textContent = total === 1 ? 'day apart' : 'days apart';

    chipsEl.appendChild(chip(span.years + ' y · ' + span.months + ' m · ' + span.days + ' d', true));
    if (total > 0) {
      chipsEl.appendChild(chip(Math.floor(total / 7) + ' w ' + (total % 7) + ' d'));
    }
    if (reversed) chipsEl.appendChild(chip('measured backwards'));

    if (reversed) {
      setMessage(msgEl,
        'End date is before the start date, so the interval is measured backwards and shown as negative.',
        'date-msg--warn');
    } else if (total === 0) {
      setMessage(msgEl, 'Both fields are the same day — the interval is zero.', '');
    } else {
      setMessage(msgEl, '', '');
    }

    clear(listEl);
    listEl.appendChild(row('Calendar span', span.years + ' y · ' + span.months + ' m · ' + span.days + ' d'));
    listEl.appendChild(row('Total days', (reversed ? '−' : '') + groupInt(total)));
    listEl.appendChild(row('Weeks', Math.floor(total / 7) + ' w ' + (total % 7) + ' d'));
    listEl.appendChild(row('Decimal weeks', (total / 7).toFixed(2)));
    listEl.appendChild(row('Business days · Mon–Fri', (reversed ? '−' : '') + groupInt(business)));
    listEl.appendChild(row('Weekend days', (reversed ? '−' : '') + groupInt(weekend)));
    listEl.appendChild(row('Both endpoints', groupInt(total + 1) + ' d'));
    listEl.appendChild(row('Leap day inside', leap ? '29 Feb ' + parts(leap).y : 'none'));
  }

  /* ---------------- derived facts ---------------- */

  function renderFacts(anchor, today) {
    if (!anchor) {
      factsForEl.textContent = 'waiting for a date';
      placeholderRows(factsEl, ['Weekday', 'ISO week', 'Day of year', 'Leap year', 'Month length', 'From today']);
      return;
    }

    var p = parts(anchor);
    var week = isoWeek(anchor);
    var doy = dayOfYear(anchor);
    var fromToday = diffDays(today, anchor);

    factsForEl.textContent = 'for ' + fmtCompact(anchor);

    clear(factsEl);
    factsEl.appendChild(row('Weekday', WEEKDAYS[anchor.getUTCDay()]));
    factsEl.appendChild(row('ISO week', 'W' + pad2(week.week) + ' · ' + week.year));
    factsEl.appendChild(row('Day of year', doy + ' of ' + daysInYear(p.y)));
    factsEl.appendChild(row('Leap year', isLeap(p.y) ? 'yes · 366 days' : 'no · 365 days'));
    factsEl.appendChild(row('Month length', daysInMonth(p.y, p.m) + ' days'));
    factsEl.appendChild(row('From today',
      fromToday === 0 ? 'today' :
      groupInt(Math.abs(fromToday)) + ' days ' + (fromToday > 0 ? 'ahead' : 'ago')));
  }

  /* ---------------- timeline ---------------- */

  function renderTimeline(start, end, today) {
    var width = timelineSvg.getBoundingClientRect().width || timelineSvg.clientWidth || 0;
    if (!width && timelineHost) width = timelineHost.clientWidth - 26;
    var W = Math.round(width);
    if (!W || W < 240) W = 560;

    var H = 112;
    var pad = 26;
    var inner = W - pad * 2;
    var axis = 62;

    var days = [serial(today)];
    if (start) days.push(serial(start));
    if (end) days.push(serial(end));
    var lo = Math.min.apply(null, days);
    var hi = Math.max.apply(null, days);
    if (hi === lo) { lo -= 1; hi += 1; }
    var padDays = Math.max(1, Math.round((hi - lo) * 0.02));
    lo -= padDays;
    hi += padDays;
    var spanDays = hi - lo;

    function xOf(date) {
      return pad + (serial(date) - lo) / spanDays * inner;
    }

    var out = [];
    var both = !!(start && end);

    /* baseline */
    out.push('<line x1="' + pad + '" y1="' + axis + '" x2="' + (W - pad) +
             '" y2="' + axis + '" stroke="rgba(240,234,221,0.16)" stroke-width="1"/>');

    /* interior date ticks keep the scale readable */
    if (both) {
      var tickCount = W < 380 ? 3 : 5;
      for (var t = 1; t < tickCount - 1; t += 1) {
        var frac = t / (tickCount - 1);
        var tx = pad + frac * inner;
        var tickDate = fromSerial(lo + Math.round(spanDays * frac));
        out.push('<line x1="' + tx.toFixed(1) + '" y1="' + (axis + 8) +
                 '" x2="' + tx.toFixed(1) + '" y2="' + (axis + 13) +
                 '" stroke="rgba(240,234,221,0.16)" stroke-width="1"/>');
        out.push('<text class="tl-text--tick" x="' + tx.toFixed(1) + '" y="' + (axis + 28) +
                 '" text-anchor="middle">' + esc(fmtTick(tickDate, spanDays)) + '</text>');
      }
    }

    var x1 = both ? xOf(start) : null;
    var x2 = both ? xOf(end) : null;

    if (both) {
      var left = Math.min(x1, x2);
      var right = Math.max(x1, x2);
      /* wash behind the measured interval */
      out.push('<rect x="' + left.toFixed(1) + '" y="' + (axis - 16) + '" width="' +
               Math.max(0, right - left).toFixed(1) + '" height="32" rx="2" fill="var(--accent-soft)"/>');
      /* the measured span itself */
      out.push('<line x1="' + x1.toFixed(1) + '" y1="' + axis + '" x2="' + x2.toFixed(1) +
               '" y2="' + axis + '" stroke="var(--accent)" stroke-width="8" stroke-linecap="round"/>');

      /* direction of travel, so a backwards interval is unmistakable */
      if (Math.abs(x2 - x1) > 34) {
        var mx = (x1 + x2) / 2;
        var dir = x2 > x1 ? 1 : -1;
        out.push('<path d="M' + (mx + dir * 5).toFixed(1) + ' ' + (axis - 4) +
                 'L' + (mx - dir * 4).toFixed(1) + ' ' + axis +
                 'L' + (mx + dir * 5).toFixed(1) + ' ' + (axis + 4) +
                 'Z" fill="var(--screen)"/>');
      }

      /* start is hollow, end is filled — the same marks as the legend */
      out.push('<circle cx="' + x1.toFixed(1) + '" cy="' + axis +
               '" r="5.5" fill="var(--screen)" stroke="var(--accent)" stroke-width="2"/>');
      out.push('<circle cx="' + x2.toFixed(1) + '" cy="' + axis +
               '" r="5.5" fill="var(--accent)"/>');
    }

    var xToday = xOf(today);
    var startIsToday = !!start && sameDay(start, today);
    var endIsToday = !!end && sameDay(end, today);
    var todayMerged = startIsToday || endIsToday;

    if (todayMerged) {
      /* a dashed halo says "this pin is also today" without a second marker */
      out.push('<circle cx="' + xToday.toFixed(1) + '" cy="' + axis +
               '" r="10" fill="none" stroke="var(--accent)" stroke-width="1" stroke-dasharray="2 3"/>');
    } else {
      out.push('<line x1="' + xToday.toFixed(1) + '" y1="' + (axis - 12) +
               '" x2="' + xToday.toFixed(1) + '" y2="' + (axis + 22) +
               '" stroke="var(--accent)" stroke-width="1" stroke-dasharray="3 3" opacity="0.75"/>');
      out.push('<circle cx="' + xToday.toFixed(1) + '" cy="' + axis +
               '" r="3.5" fill="var(--screen)" stroke="var(--accent)" stroke-width="1.5"/>');
    }

    /* pin labels, staggered when they crowd each other */
    var pins = [];
    if (start) pins.push({ x: x1, name: 'from', date: start, kind: 'from', now: startIsToday });
    if (end) pins.push({ x: x2, name: 'to', date: end, kind: 'to', now: endIsToday });
    if (!todayMerged) pins.push({ x: xToday, name: 'today', date: null, kind: 'today', now: true });
    pins.sort(function (a, b) { return a.x - b.x; });

    var rowLast = [-Infinity, -Infinity, -Infinity];
    for (var i = 0; i < pins.length; i += 1) {
      var r = 0;
      while (r < rowLast.length && pins[i].x - rowLast[r] < 132) r += 1;
      if (r === rowLast.length) {
        r = 0;
        if (rowLast[1] < rowLast[r]) r = 1;
        if (rowLast[2] < rowLast[r]) r = 2;
      }
      rowLast[r] = pins[i].x;
      pins[i].row = r;
    }

    function estimate(pin) {
      var label = pin.name + (pin.date ? ' ' + fmtShort(pin.date) : '') +
                  (pin.now && pin.kind !== 'today' ? ' · today' : '');
      return label.length * 6.2 + 4;
    }

    for (var k = 0; k < pins.length; k += 1) {
      var pin = pins[k];
      var labelW = estimate(pin);
      var anchor = pin.kind === 'from' ? 'start' : (pin.kind === 'to' ? 'end' : 'middle');
      if (anchor === 'middle') {
        if (pin.x - labelW / 2 < 2) anchor = 'start';
        else if (pin.x + labelW / 2 > W - 2) anchor = 'end';
      } else if (anchor === 'start' && pin.x + labelW > W - 2) {
        anchor = 'end';
      } else if (anchor === 'end' && pin.x - labelW < 2) {
        anchor = 'start';
      }
      var px = Math.max(2, Math.min(pin.x, W - 2));
      var py = 14 + pin.row * 16;

      var body = '<tspan class="tl-text--name">' + esc(pin.name) + '</tspan>';
      if (pin.date) {
        body += '<tspan dx="5">' + esc(fmtShort(pin.date)) + '</tspan>';
      }
      if (pin.now && pin.kind !== 'today') {
        body += '<tspan class="tl-text--now" dx="4">· today</tspan>';
      }
      var cls = pin.kind === 'today' ? 'tl-text--name tl-text--now' : 'tl-text--pin';
      out.push('<text class="' + cls + '" x="' + px.toFixed(1) + '" y="' + py +
               '" text-anchor="' + anchor + '">' + body + '</text>');

      /* stem from the label row down to the axis */
      if (pin.kind !== 'today') {
        out.push('<line x1="' + pin.x.toFixed(1) + '" y1="' + (py + 5) +
                 '" x2="' + pin.x.toFixed(1) + '" y2="' + (axis - 12) +
                 '" stroke="var(--accent-line)" stroke-width="1"/>');
      }
    }

    /* screen-reader summary of what the drawing shows */
    var aria;
    if (both) {
      var loEnd = Math.min(serial(start), serial(end));
      var hiEnd = Math.max(serial(start), serial(end));
      var rel;
      if (serial(today) < loEnd) {
        rel = 'today is ' + (loEnd - serial(today)) + ' days before the interval';
      } else if (serial(today) > hiEnd) {
        rel = 'today is ' + (serial(today) - hiEnd) + ' days after the interval';
      } else {
        rel = 'today falls inside the interval';
      }
      aria = 'Timeline from ' + fmtShort(start) + ' to ' + fmtShort(end) +
             ' (' + Math.abs(serial(end) - serial(start)) + ' days), drawn to scale; ' +
             fmtShort(today) + ': ' + rel + '.';
    } else {
      aria = 'Timeline showing today, ' + fmtShort(today) + '; waiting for a start and an end date.';
    }
    timelineSvg.setAttribute('aria-label', aria);
    timelineSvg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    timelineSvg.innerHTML = out.join('');

    /* the caption states the scale, so "proportional" is verifiable */
    if (both) {
      var dayCount = Math.abs(diffDays(start, end));
      var perPx = spanDays / inner;
      var perText = perPx < 1 ? perPx.toFixed(2) : (perPx < 10 ? perPx.toFixed(1) : perPx.toFixed(0));
      scaleEl.textContent = dayCount + (dayCount === 1 ? ' day' : ' days') +
        ' over ' + Math.round(inner) + ' px · 1 px ≈ ' + perText + ' d';
    } else {
      scaleEl.textContent = 'waiting for both dates';
    }
  }

  /* ---------------- shift arithmetic ---------------- */

  function setShiftDir(dir) {
    shiftDir = dir;
    shiftAdd.setAttribute('aria-pressed', String(dir === 1));
    shiftSub.setAttribute('aria-pressed', String(dir === -1));
  }

  function shiftFail(text) {
    shiftDateOut.textContent = '—';
    shiftMeta.textContent = '';
    setMessage(shiftMsg, text, 'sci-msg--error');
  }

  function renderShift() {
    var parsed = parseInput(shiftInput.value);
    if (!parsed.ok) {
      shiftFail(parsed.error);
      return;
    }

    var raw = shiftAmount.value == null ? '' : String(shiftAmount.value).trim();
    if (!/^\d+$/.test(raw)) {
      shiftFail('Amount must be a whole number, 0 or more.');
      return;
    }
    var amount = parseInt(raw, 10);
    if (amount > 100000) {
      shiftFail('Keep the amount at 100,000 or less.');
      return;
    }

    var unit = shiftUnit.value;
    var date = parsed.date;
    var result;
    if (unit === 'days') result = addDays(date, shiftDir * amount);
    else if (unit === 'weeks') result = addDays(date, shiftDir * amount * 7);
    else if (unit === 'months') result = addMonthsSat(date, shiftDir * amount);
    else result = addYearsSat(date, shiftDir * amount);

    if (!inRange(result)) {
      shiftFail('That shift takes the date outside the years 1 to 9999.');
      return;
    }

    shiftDateOut.textContent = fmtLong(result);
    shiftMeta.textContent = fmtShort(date) + ' ' + (shiftDir > 0 ? '+' : '−') + ' ' +
      plural(amount, unit) + ' · ' + isoValue(result);

    var clamped = (unit === 'months' || unit === 'years') &&
                  parts(result).d !== parts(date).d;
    if (clamped) {
      setMessage(shiftMsg,
        'Day ' + parts(date).d + ' does not exist in the target month, so the result clamps to day ' +
        parts(result).d + '.', '');
    } else if (amount === 0) {
      setMessage(shiftMsg, 'A zero shift leaves the date unchanged.', '');
    } else {
      setMessage(shiftMsg, '', '');
    }
  }

  /* ---------------- presets + render ---------------- */

  function syncPresets(from, to, today) {
    var active = '';
    if (from.ok && to.ok) {
      var p = parts(today);
      if (sameDay(from.date, today) && sameDay(to.date, today)) active = 'today';
      else if (sameDay(from.date, addDays(today, -7)) && sameDay(to.date, today)) active = 'last7';
      else if (sameDay(from.date, utc(p.y, p.m, 1)) && sameDay(to.date, today)) active = 'mtd';
      else if (sameDay(from.date, utc(p.y, 1, 1)) && sameDay(to.date, today)) active = 'ytd';
    }
    for (var i = 0; i < presetBtns.length; i += 1) {
      presetBtns[i].classList.toggle('is-on', presetBtns[i].getAttribute('data-preset') === active);
    }
  }

  function applyPreset(name) {
    var today = todayDate();
    var p = parts(today);
    if (name === 'today') {
      fromInput.value = isoValue(today);
      toInput.value = isoValue(today);
    } else if (name === 'last7') {
      fromInput.value = isoValue(addDays(today, -7));
      toInput.value = isoValue(today);
    } else if (name === 'mtd') {
      fromInput.value = isoValue(utc(p.y, p.m, 1));
      toInput.value = isoValue(today);
    } else if (name === 'ytd') {
      fromInput.value = isoValue(utc(p.y, 1, 1));
      toInput.value = isoValue(today);
    }
    render();
  }

  function render() {
    var today = todayDate();
    var from = parseInput(fromInput.value);
    var to = parseInput(toInput.value);
    var p = parts(today);

    metaEl.textContent = 'today ' + fmtShort(today) + ' · calendar days at UTC noon';

    renderInterval(from, to, today);
    renderFacts(from.ok ? from.date : today, today);
    syncPresets(from, to, today);
    renderTimeline(from.ok ? from.date : null, to.ok ? to.date : null, today);
    renderShift();
  }

  /* ---------------- wiring ---------------- */

  fromInput.addEventListener('input', render);
  fromInput.addEventListener('change', render);
  toInput.addEventListener('input', render);
  toInput.addEventListener('change', render);

  for (var i = 0; i < presetBtns.length; i += 1) {
    (function (btn) {
      btn.addEventListener('click', function () {
        applyPreset(btn.getAttribute('data-preset'));
      });
    })(presetBtns[i]);
  }

  shiftInput.addEventListener('input', renderShift);
  shiftInput.addEventListener('change', renderShift);
  shiftAmount.addEventListener('input', renderShift);
  shiftAmount.addEventListener('change', renderShift);
  shiftUnit.addEventListener('change', renderShift);

  shiftAdd.addEventListener('click', function () { setShiftDir(1); renderShift(); });
  shiftSub.addEventListener('click', function () { setShiftDir(-1); renderShift(); });

  /* weekday/ISO facts depend on the host clock, refresh on focus if the day rolled over */
  var lastToday = serial(todayDate());
  window.addEventListener('focus', function () {
    if (serial(todayDate()) !== lastToday) {
      lastToday = serial(todayDate());
      render();
    }
  });

  var resizeQueued = false;
  function onResize() {
    if (resizeQueued) return;
    resizeQueued = true;
    window.requestAnimationFrame(function () {
      resizeQueued = false;
      if (document.body.getAttribute('data-mode') === 'date') render();
    });
  }
  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', onResize);

  document.addEventListener('fluxion:modechange', function (event) {
    if (!event.detail || event.detail.mode !== 'date') return;
    window.requestAnimationFrame(render);
  });

  /* ---------------- first paint ---------------- */

  (function init() {
    var today = todayDate();
    fromInput.value = isoValue(today);
    toInput.value = isoValue(addDays(today, 30));
    shiftInput.value = isoValue(today);
    setShiftDir(1);
    render();
  })();
})();

