import re
from html.parser import HTMLParser
s=open('preview.html',encoding='utf-8').read()

VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errs=[]; self.ids=[]; self.aria=[]
    def handle_starttag(self,tag,attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append(d['id'])
        for k in ('aria-labelledby','aria-controls','aria-describedby'):
            if k in d: self.aria.append((k,d[k]))
        if tag not in VOID: self.stack.append((tag,self.getpos()))
    def handle_startendtag(self,tag,attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append(d['id'])
    def handle_endtag(self,tag):
        if tag in VOID: return
        if not self.stack: self.errs.append(('extra close',tag,self.getpos())); return
        if self.stack[-1][0]!=tag:
            self.errs.append(('mismatch',tag,self.getpos(),self.stack[-1]))
            # try to recover
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    del self.stack[i:]; break
        else:
            self.stack.pop()
p=P(); p.feed(s)
print('unclosed:',p.stack[:5]); print('mismatches:',p.errs[:5])
from collections import Counter
c=Counter(p.ids); print('dup ids:',[k for k,v in c.items() if v>1])
missing=[]
for k,v in p.aria:
    for ref in v.split():
        if ref not in c: missing.append((k,ref))
print('missing aria refs:',missing)
